import os
from taf.ul.sc.unix_functionality import UnixFunctionality
from taf.ul.sc.util import util
from taf.ul.sc.uesim.rtg_config_converter import RtgConfigConverter
from taf.ul.sc.util.helpers import is_dry_run


class GenericWorkstation(UnixFunctionality):
    """Class with keywords for RTG Executor Workstation."""

    root_state = "WS_ROOT"
    basic_state = "WS"

    def __init__(self,
                 device_name='RTG_WS',                              # type: 'Optional[str]'
                 device=None,                                       # type: 'Optional[RTG]'
                 autoconnect=True,                                  # type: 'Optional[bool]'
                 scenarios_dir='/home/rtg/test/scenarios/',         # type: 'Optional[str]'
                 logs_dir='/home/rtg/logs/',                        # type: 'Optional[str]'
                 config_dir='/opt/rtg/etc',                         # type: 'Optional[str]'
                 config_file='rtg.ini',                             # type: 'Optional[str]'
                 dhcp_configuration_file='/etc/dhcp/dhcpd.conf',    # type: 'Optional[str]'
                 ue_cap_dir='/home/rtg/test/ue_capabilities/',      # type: 'Optional[str]'
                 get_device=False                                   # type: 'Optional[bool]'
                 ):
        """
        :param device_name: Moler device name - by default RTG_WS.
        :param device Moler RTG device. Initial state should be set to WS
        :param autoconnect: Connect to device after create object.
        :param scenarios_dir: Path to directory with test scenarios.
        :param logs_dir: Base path to directory with execution logs.
        :param config_dir: Path to directory with rtg configuration.
        :param config_file: Ini config file name.
        :param ue_cap_dir: Path to directory with rtg UE CAP configuration.
        :param dhcp_configuration_file: path to dhcpd.conf file.
        """
        super(GenericWorkstation, self).__init__(device_name=device_name, device=device,
                                                 autoconnect=autoconnect, get_device=get_device)
        self.scenarios_dir = scenarios_dir
        self.logs_dir = logs_dir
        self.config_dir = config_dir
        self.config_file = config_file
        self.dhcp_configuration_file = dhcp_configuration_file
        self.ue_cap_dir = ue_cap_dir
        if autoconnect and not is_dry_run():
            self.device.goto_state(self.basic_state)

    def collect_dhcp_configuration_file(self, destination_dir):
        """
        SCP dhcpd.conf file from RTG workstation to UnixLocal.
        :param destination_dir: Target directory where dhcpd.conf will be downloaded
        :return: None
        """
        util().download_files(local_dir=destination_dir,
                              remote_file=os.path.basename(self.dhcp_configuration_file),
                              remote_dir=os.path.dirname(self.dhcp_configuration_file),
                              remote_device_name=self.name
                              )

    def collect_ue_capabilities_file(self, execution_dir, destination_dir):
        """
        SCP scenario_ue_capabilities.txt file from RTG workstation to UnixLocal.
        :param execution_dir: Subpath to logs execution dir. eg: attach_auto/20190807-163723/
        :param destination_dir: Target directory where scenario_ue_capabilities.txt will be downloaded
        :return: None
        """
        util().download_files(local_dir=destination_dir,
                              remote_file="scenario_ue_capabilities.txt",
                              remote_dir=os.path.join(self.logs_dir, execution_dir),
                              remote_device_name=self.name
                              )

    def collect_ue_db_file(self, execution_dir, destination_dir):
        """
        SCP ue_db.txt file from RTG workstation to UnixLocal.
        :param execution_dir: Subpath to logs execution dir. eg: attach_auto/20190807-163723/
        :param destination_dir: Target directory where ue_db.txt will be downloaded
        :return: None
        """
        util().download_files(local_dir=destination_dir,
                              remote_file="ue_db.txt",
                              remote_dir=os.path.join(self.logs_dir, execution_dir),
                              remote_device_name=self.name
                              )

    def collect_scenario_file(self, execution_dir, scenario_name, destination_dir):
        """
        SCP test scenario file from RTG workstation to UnixLocal.
        :param execution_dir: Subpath to logs execution dir. eg: attach_auto/20190807-163723/
        :param scenario_name: scenario name - without extension
        :param destination_dir: Target directory where scenario will be downloaded
        :return: None
        """
        util().download_files(local_dir=destination_dir,
                              remote_file="{}.scn".format(scenario_name),
                              remote_dir=os.path.join(self.logs_dir, execution_dir),
                              remote_device_name=self.name
                              )

    def collect_test_report(self, execution_dir, destination_dir, timeout=60):
        """
        SCP test execution report from RTG workstation to UnixLocal.
        :param execution_dir: Subpath to logs execution dir. eg: attach_auto/20190807-163723/
        :param destination_dir: Target directory where rtg report will be downloaded
        :param timeout: timeout for executing command
        :return: None
        """
        util().download_files(local_dir=os.path.join(destination_dir, execution_dir, 'report'),
                              remote_file='*',
                              remote_dir=os.path.join(self.logs_dir, execution_dir, 'report'),
                              remote_device_name=self.name,
                              timeout=timeout
                              )

    def collect_mmi_ctrl_files(self, execution_dir, destination_dir, timeout=180):
        """
        SCP all mmi_ctrl files from RTG workstation to UnixLocal.
        :param execution_dir: Subpath to logs execution dir. eg: attach_auto/20190807-163723/
        :param destination_dir: Target directory where mmi_ctrl files will be downloaded
        :param timeout: timeout for executing command
        :return: None
        """
        util().download_files(local_dir=os.path.join(destination_dir, execution_dir),
                              remote_file="mmi_*",
                              remote_dir=os.path.join(self.logs_dir, execution_dir),
                              remote_device_name=self.name,
                              timeout=timeout
                              )

    def collect_syslog_ctrl_files(self, execution_dir, destination_dir, timeout=180):
        """
        SCP syslog_ctrl files from RTG workstation to UnixLocal.
        :param execution_dir: Subpath to logs execution dir. eg: attach_auto/20190807-163723/
        :param destination_dir: Target directory where syslog_ctrl files will be downloaded
        :param timeout: timeout for executing command
        :return: None
        """
        util().download_files(local_dir=os.path.join(destination_dir, execution_dir),
                              remote_file="syslog_ctrl*",
                              remote_dir=os.path.join(self.logs_dir, execution_dir),
                              remote_device_name=self.name,
                              timeout=timeout
                              )

    def upload_configuration(self, config_path, raise_exception=False):
        """Change content of rtg.ini file on workstation to content from given local file.

        :param config_path: Path to local file with configuration to be placed in rtg.ini
        :param raise_exception: raise exception when scp fail. Otherwise only warning will be visible.
        :return: None
        """
        log_level = 'error' if raise_exception else 'warning'

        util().upload_files(local_dir=os.path.dirname(config_path),
                            local_file=os.path.basename(config_path),
                            remote_dir=self.config_dir,
                            remote_device_name=self.name,
                            new_file_name=self.config_file,
                            log_level=log_level
                            )

    def upload_ue_cap(self, ue_cap_file, raise_exception=False):
        """
        SCP UE CAP file from localhost to RTG workstation
        :param ue_cap_file: path to file or list to ue_cap_files
        :param raise_exception: raise exception when scp fail. Otherwise only warning will be visible.
        :return: None
        """
        log_level = 'error' if raise_exception else 'warning'
        ue_cap_files = ue_cap_file if isinstance(ue_cap_file, list) else [ue_cap_file]

        for ue_cap in ue_cap_files:
            remote_dir = self.config_dir if ue_cap.endswith('.ini') else self.ue_cap_dir
            util().upload_files(local_dir=os.path.dirname(ue_cap),
                                local_file=os.path.basename(ue_cap),
                                remote_dir=remote_dir,
                                remote_device_name=self.name,
                                log_level=log_level
                                )

    def upload_ue_db(self, ue_db_file, raise_exception=False):
        """
        SCP UE DB file from localhost to RTG workstation
        :param ue_db_file: path to ue_db file
        :param raise_exception: raise exception when scp fail. Otherwise only warning will be visible.
        :return: None
        """
        log_level = 'error' if raise_exception else 'warning'

        util().upload_files(local_dir=os.path.dirname(ue_db_file),
                            local_file=os.path.basename(ue_db_file),
                            remote_dir=self.config_dir,
                            remote_device_name=self.name,
                            log_level=log_level
                            )

    def update_configuration(self, params_to_update=None):
        """Update rtg.ini file by dictionary passed as parameter.

        :param params_to_update: Dictionary with configs to update
        :return: None
        """
        config = self.get_file_content(os.path.join(self.config_dir, self.config_file))
        config = RtgConfigConverter('\n'.join(config)).get_config_dict()

        config = RtgConfigConverter.dict_merge(config, params_to_update)
        config_string = RtgConfigConverter(config).get_config_string()

        cmd = self.device.get_cmd(cmd_name='tee', cmd_params={'path': os.path.join(self.config_dir, self.config_file),
                                                              'content': config_string})
        cmd(timeout=10)
